css:
.fx-fnews .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;padding:.9em 1.5em;border-radius:var(--radius);font:700 .95em var(--font-body);text-decoration:none;border:1.5px solid var(--primary);background:var(--primary);color:var(--on-primary);cursor:pointer;transition:transform calc(.25s/var(--speed)),box-shadow calc(.25s/var(--speed))}
.fx-fnews .btn:hover{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-fnews .btn.ghost{background:transparent;color:var(--primary)}
.fx-fnews .btn:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-fnews{display:flex;flex-direction:column;background:var(--surface)}
.fx-fnews .page{flex:1;display:grid;align-content:center;justify-items:center;text-align:center;gap:.8em;padding:4em 1.25em}.fx-fnews .page h1{font-size:clamp(1.8em,4vw,2.8em)}.fx-fnews .page p{opacity:.65}
.fx-fnews .ft{padding:0 max(5vw,1.25em) 1.6em}
.fx-fnews .fi{width:min(1120px,100%);margin:0 auto;display:grid;gap:3em}
.fx-fnews .sub{display:grid;grid-template-columns:1.1fr 1fr;gap:2.4em;align-items:center;padding:2.6em;border-radius:calc(var(--radius)*1.8);background:var(--primary);color:var(--on-primary);position:relative;overflow:hidden}
.fx-fnews .sub::after{content:"";position:absolute;width:20em;aspect-ratio:1;right:-6em;top:-9em;border-radius:50%;background:var(--accent);opacity:.28;pointer-events:none}
.fx-fnews .sub>div{position:relative;z-index:1}.fx-fnews .sub h2{font-size:clamp(1.6em,3.2vw,2.3em)}.fx-fnews .sub p{opacity:.82;margin-top:.6em;max-width:36ch}
.fx-fnews form{position:relative;z-index:1;display:grid;gap:.7em}
.fx-fnews .row{display:flex;gap:.5em;padding:.4em;border-radius:calc(var(--radius)*1.2);background:var(--surface)}
.fx-fnews input{flex:1;min-width:0;border:0;background:transparent;color:var(--text);font:500 1em var(--font-body);padding:.7em .8em;border-radius:var(--radius)}
.fx-fnews input::placeholder{color:var(--text);opacity:.45}.fx-fnews input:focus-visible{outline:2px solid var(--accent);outline-offset:0}
.fx-fnews .go{border:0;cursor:pointer;padding:.7em 1.3em;border-radius:var(--radius);background:var(--accent);color:var(--on-accent);font:700 .95em var(--font-body);transition:transform calc(.2s/var(--speed))}
.fx-fnews .go:hover{transform:translateY(-1px)}.fx-fnews .go:focus-visible{outline:2px solid var(--text);outline-offset:2px}
.fx-fnews .note{font-size:.82em;opacity:.78;min-height:1.3em}
.fx-fnews .vh{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.fx-fnews .main{display:grid;grid-template-columns:1.3fr 2fr;gap:3em}
.fx-fnews .brand b{display:block;font:600 1.6em var(--font-heading);margin-bottom:.4em}.fx-fnews .brand p{opacity:.65;max-width:28ch;font-size:.95em}
.fx-fnews .cols{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4em}
.fx-fnews h3{font:700 .72em var(--font-body);letter-spacing:.14em;text-transform:uppercase;opacity:.5;margin-bottom:1em}
.fx-fnews ul{list-style:none;margin:0;padding:0;display:grid;gap:.6em}
.fx-fnews .ft a{color:var(--text);text-decoration:none;opacity:.8;font-size:.95em}.fx-fnews .ft a:hover{opacity:1;color:var(--primary);text-decoration:underline;text-underline-offset:.25em}
.fx-fnews .ft a:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:3px}
.fx-fnews .bot{display:flex;justify-content:space-between;gap:1em;flex-wrap:wrap;padding-top:1.4em;border-top:1px solid var(--border);font-size:.85em;opacity:.7}.fx-fnews .bot nav{display:flex;gap:1.4em}
@media(max-width:820px){.fx-fnews .sub{grid-template-columns:1fr;padding:1.8em 1.4em}.fx-fnews .main{grid-template-columns:1fr;gap:2em}.fx-fnews .row{flex-direction:column;background:transparent;padding:0}.fx-fnews input{background:var(--surface);border-radius:var(--radius)}.fx-fnews .go{padding:.9em}}
@media(prefers-reduced-motion:reduce){.fx-fnews .go{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-fnews .btn.is-tap{transform:translateY(-2px);box-shadow:0 12px 24px -14px var(--primary)}
.fx-fnews .go.is-tap{transform:translateY(-1px)}
.fx-fnews .ft a.is-tap{opacity:1;color:var(--primary);text-decoration:underline;text-underline-offset:.25em}

js:
document.querySelectorAll('.fx-fnews form').forEach(function(f){var i=f.querySelector('input'),n=f.querySelector('.note');f.addEventListener('submit',function(e){e.preventDefault();
if(!i.checkValidity()||!i.value){n.textContent='Please enter a valid email address.';i.setAttribute('aria-invalid','true');i.focus();return}
i.removeAttribute('aria-invalid');n.textContent='Thanks! Check your inbox to confirm.';i.value=''})});
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
